{% set p = get_wholesale_print_data(doc) %}{% set company = p.company %}{% set customer = p.customer %}{% set show_images = 1 if doc.get('custom_print_color_images') is none else doc.get('custom_print_color_images') %}{% set show_item_name = 1 if doc.get('custom_print_item_name') is none else doc.get('custom_print_item_name') %}{% set show_sku = 1 if doc.get('custom_print_sku') is none else doc.get('custom_print_sku') %}{% set show_color_code = 1 if doc.get('custom_print_color_code') is none else doc.get('custom_print_color_code') %}{% set show_description = 1 if doc.get('custom_print_description') is none else doc.get('custom_print_description') %}
<h2>Guia de Remessa</h2>
{% if doc.docstatus != 1 %}<div class="warning">{{ 'RASCUNHO / 草稿' if doc.docstatus == 0 else 'CANCELADO / 已取消' }} — 非正式凭证</div>{% endif %}
{% if p.get('legacy') %}<div class="warning">历史单据未保存打印快照，所示补充主资料为当前资料。</div>{% endif %}
<table class="meta"><tr><td><b>{{ company.name | e }}</b><br>NUIT: {{ company.nuit | e }}<br>{{ company.address }}<br>Tel: {{ company.phone | e }}</td><td><b>Cliente / 客户: {{ customer.name | e }}</b><br>NUIT: {{ customer.nuit or 'Não informado / 未提供' | e }}<br>Loja / 门店: {{ customer.store | e }}<br>{{ customer.address }}<br>{{ customer.contact }} · {{ customer.phone | e }}</td></tr><tr><td>N.º / 编号: {{ doc.name | e }}<br>客户订单号: {{ doc.get('custom_customer_order_no') or '—' | e }}<br>订单: {{ p.order.name | e }}</td><td>Data / 日期: {{ doc.get('posting_date') or doc.get('transaction_date') }}<br>起运: {{ p.transport.departure_time | e }}<br>仓库地址: {{ p.transport.source_address | e }}</td></tr></table>
<table><thead><tr><th colspan="{{ 7 + show_images + show_item_name + show_sku + show_color_code + show_description }}">{{ doc.name | e }} · 本次送货 / Entrega</th></tr><tr>{% if show_images %}<th>图片</th>{% endif %}{% if show_item_name %}<th>Artigo / 商品</th>{% endif %}{% if show_sku %}<th>SKU / 货号</th>{% endif %}{% if show_color_code %}<th>色号 / Cor</th>{% endif %}<th>条码 / Código de barras</th>{% if show_description %}<th>描述 / Descrição</th>{% endif %}<th>订购 / 此前</th><th>本次 / 剩余</th><th>Un.</th><th>Preço / 单价</th><th>Valor / 金额</th><th>追溯</th></tr></thead><tbody>
{% for item in p['items'] %}<tr>{% if show_images %}<td>{% if item.image %}<img class="photo" src="{{ item.image | e }}">{% endif %}</td>{% endif %}{% if show_item_name %}<td>{{ item.item_name | e }}</td>{% endif %}{% if show_sku %}<td>{{ item.order_code or item.item_code | e }}</td>{% endif %}{% if show_color_code %}<td>{{ item.color_code | e }}{% if item.color %}<br>{{ item.color | e }}{% endif %}</td>{% endif %}<td>{{ item.barcode | e }}</td>{% if show_description %}<td>{{ item.description | e }}</td>{% endif %}<td class='num'>{{ item.ordered_qty if item.ordered_qty is not none else '—' }} / {{ item.delivered_before_qty if item.delivered_before_qty is not none else '—' }}</td><td class='num'>{{ item.qty }} / {{ item.remaining_qty if item.remaining_qty is not none else '—' }}</td><td>{{ item.uom | e }}</td><td class="num">{{ frappe.utils.fmt_money(item.rate, currency=doc.currency) }}</td><td class="num">{{ frappe.utils.fmt_money(item.amount, currency=doc.currency) }}</td><td>{{ item.batch_no | e }} {{ item.serial_no | e }} {{ item.serial_and_batch_bundle | e }}</td></tr>{% endfor %}
</tbody></table><div class="block num">Total / 含税合计: {{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</div>
<div class="block">运输: {{ p.transport.vehicle_no | e }} · {{ p.transport.driver_name | e }} · {{ p.transport.driver_phone | e }}<br>包装: 箱数 {{ doc.get('custom_box_count') or '—' }} · 托盘数 {{ doc.get('custom_pallet_count') or '—' }}</div>
{% set invoices = get_delivery_invoice_names(doc.name) if not doc.is_new() else [] %}<div class="block">发票: {{ invoices | join(', ') | e if invoices else '未开票或无权查看关联发票' }}<br>开票安排: {{ p.invoice_plan or '未填写具体安排' | e }}</div>
<div class="block">差异 / 退货备注: {{ doc.get('custom_delivery_notes') or '' | e }}</div><div class="block sign">客户签收姓名 / Nome: {{ doc.get('custom_signature_name') or '________________' | e }}<br><br>签字 / Assinatura: ____________________ 日期 / Data: {{ doc.get('custom_signature_date') or '________________' }}<br><br>司机确认: ____________________ 差异: ____________________</div>
{% if doc.get('custom_print_color_qr') %}{% set seen = [] %}<div class="block">{% for item in p['items'] %}{% if item.template_code and item.template_code not in seen %}{% set unused = seen.append(item.template_code) %}{% set qr = get_color_card_qr_img(item.template_code) %}{% if qr %}<img class="qr" src="{{ qr | e }}">{{ item.template_code | e }} {% endif %}{% endif %}{% endfor %}</div>{% endif %}
<div id="footer-html" class="visible-pdf"><div class="text-center">{{ doc.name | e }} · <span class="page"></span> / <span class="topage"></span></div></div>
